
(function(){
 const BYTE_BACK={"S20":"data:image/webp;base64,","S21":"data:image/webp;base64,","S22":"data:image/webp;base64,","S23":"data:image/webp;base64,","S24":"data:image/webp;base64,","S19":"data:image/webp;base64,","S18":"data:image/webp;base64,","S17":"data:image/webp;base64,","S16":"data:image/webp;base64,","S15":"data:image/webp;base64,","S14":"data:image/webp;base64,","S13":"data:image/webp;base64,","S12":"data:image/webp;base64,","S11":"data:image/webp;base64,","S10":"data:image/webp;base64,","S01":"data:image/webp;base64,","S02":"data:image/webp;base64,","S03":"data:image/webp;base64,","S04":"data:image/webp;base64,","S05":"data:image/webp;base64,","S06":"data:image/webp;base64,","S07":"data:image/webp;base64,","S08":"data:image/webp;base64,","S09":"data:image/webp;base64,"};
 function sidOf(card){
   const m=((card.dataset.member||"")+" "+(card.textContent||"")).match(/S\s*0?(\d{1,2})/i);
   return m ? "S"+String(parseInt(m[1],10)).padStart(2,"0") : "";
 }
 document.querySelectorAll("#memberGrid .member-card").forEach(card=>{
   const sid=sidOf(card), src=BYTE_BACK[sid];
   if(!src) return;
   const back=card.querySelector(".member-back");
   if(!back || back.querySelector(".bytes-profile-badge")) return;
   const badge=document.createElement("div");
   badge.className="bytes-profile-badge";
   badge.innerHTML='<img loading="lazy" decoding="async" decoding="async" src="'+src+'" alt="'+sid+' byteS 캐릭터">';
   back.appendChild(badge);
 });
})();
